using System.Net.Http.Json;using System.Text.Json;using Microsoft.EntityFrameworkCore;
namespace Decont;
public record ExternalSupplierResult(string State,bool? Valid,string? Name,string MessageRo,string MessageEn);
public interface ISupplierValidator{Task<ExternalSupplierResult> Check(string cui,DateOnly date,CancellationToken ct);}
public class SupplierValidator(IConfiguration config):ISupplierValidator{public async Task<ExternalSupplierResult> Check(string cui,DateOnly date,CancellationToken ct){var endpoint=config["SupplierValidation:Endpoint"];if(string.IsNullOrEmpty(endpoint))return new("NotConfigured",null,null,"Verificarea externă nu este configurată.","External validation is not configured.");try{Guard.Require(Uri.TryCreate(endpoint,UriKind.Absolute,out var uri)&&uri.Scheme=="https","configuration","Serviciul extern necesită HTTPS.","External service requires HTTPS.");using var client=new HttpClient{Timeout=TimeSpan.FromSeconds(8)};if(config["SupplierValidation:ApiKey"] is string key)client.DefaultRequestHeaders.Add("X-API-Key",key);var response=await client.PostAsJsonAsync(uri,new{country="RO",cui,date=date.ToString("yyyy-MM-dd")},ct);response.EnsureSuccessStatusCode();var json=await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken:ct);var valid=json.GetProperty("valid").GetBoolean();return new("Verified",valid,json.TryGetProperty("name",out var name)?name.GetString():null,valid?"Validat de serviciul extern.":"Serviciul extern nu confirmă CUI-ul.",valid?"Validated by external service.":"External service does not confirm the VAT ID.");}catch(Exception ex)when(ex is HttpRequestException or TaskCanceledException or JsonException or DomainException or InvalidOperationException){return new("Unavailable",null,null,"Serviciul extern nu este disponibil. Finance poate verifica manual cu motiv.","External service is unavailable. Finance can verify manually with a reason.");}}}
public static class SupplierValidation{public static void Map(RouteGroupBuilder api){api.MapPost("/suppliers/validate",async(SupplierCheckInput i,ISupplierValidator validator,Reports svc,Db db,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{var cui=Rules.Cui(i.Cui);Guard.Require(Rules.ValidCui(cui),"cui","CUI invalid.","Invalid CUI.");var result=await validator.Check(cui,i.Date,c.RequestAborted);svc.Log(c.User,null,cui,"SupplierExternallyChecked",after:result);return result;}));api.MapPost("/suppliers/validation-override",async(SupplierOverrideInput i,Reports svc,Db db,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{Guard.Reason(i.Reason);Guard.Require(Rules.ValidCui(i.Cui),"cui","CUI invalid.","Invalid CUI.");svc.Log(c.User,null,Rules.Cui(i.Cui),"SupplierValidationOverridden",after:new{i.Date},reason:i.Reason);return new{state="ManuallyVerified"};})).RequireAuthorization(p=>p.RequireRole("Finance"));}}
public record SupplierCheckInput(string Cui,DateOnly Date);public record SupplierOverrideInput(string Cui,DateOnly Date,string Reason);
